1	#!/usr/bin/env node
2	/**
3	 * dispatch-evidence.mjs — kumitate lane gate, contract kumitate-dispatch-evidence-v1.
4	 *
5	 *   node scripts/dispatch-evidence.mjs --root DIR --round N --wave NAME [--expect planned=N,sessions=N,exit0=N,reports=N]
6	 *   node scripts/dispatch-evidence.mjs --selftest
7	 *
8	 * Verdict: DISPATCH_EVIDENCE: CLEAN (seats=… sessions=… exit0=… reports=… dead=…)
9	 *          0 clean · 1 a real defect (DRIFT) · 2 fail-closed · 64 usage
10	 *
11	 * What it reads: the round's ACTUAL dispatch record — the launcher progress file the
12	 * dispatcher wrote seat by seat (`launcher-progress.tsv`) and the summary a report quotes
13	 * (`dispatch-actual.json`) — plus the seat report files the progress file's seats name.
14	 * A prepared spec is not a dispatch: a registry whose members carry no session id is
15	 * DRIFT NOT_A_DISPATCH, never a dispatch of N seats. A dead seat (exit != 0, no session
16	 * id) is named and never credited.
17	 *
18	 * Findings: PLAN_MISMATCH, SESSION_MISMATCH, REPORT_ABSENT, DEAD_SEAT_UNCREDITED,
19	 * DEAD_MISMATCH, REGISTRY_MISMATCH, NOT_A_DISPATCH, EXPECT_MISMATCH, and the
20	 * fail-closed ids PROGRESS_ABSENT, REGISTRY_UNREADABLE, WAVE_DIR_ABSENT.
21	 */
22	import { spawnSync } from 'node:child_process';
23	import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
24	import { tmpdir } from 'node:os';
25	import { join, resolve } from 'node:path';
26	
27	const CONTRACT = 'kumitate-dispatch-evidence-v1';
28	const PROGRESS = 'launcher-progress.tsv';
29	const REGISTRY = 'dispatch-actual.json';
30	
31	function usage(msg) {
32	  process.stderr.write(`DISPATCH_EVIDENCE: USAGE ${msg}\n`);
33	  process.exit(64);
34	}
35	
36	function parseArgs(argv) {
37	  const out = { root: process.cwd(), round: null, wave: null, expect: null, selftest: false };
38	  for (let i = 0; i < argv.length; i += 1) {
39	    const a = argv[i];
40	    if (a === '--selftest') out.selftest = true;
41	    else if (a === '--root') out.root = argv[++i];
42	    else if (a === '--round') out.round = argv[++i];
43	    else if (a === '--wave') out.wave = argv[++i];
44	    else if (a === '--expect') out.expect = argv[++i];
45	    else usage(`unknown argument ${JSON.stringify(a)}`);
46	  }
47	  return out;
48	}
49	
50	function parseProgress(txt) {
51	  const rows = [];
52	  for (const line of txt.split('\n')) {
53	    if (!line.trim()) continue;
54	    const parts = line.split('\t');
55	    const name = parts[0];
56	    const kv = {};
57	    for (const p of parts.slice(1)) {
58	      const i = p.indexOf('=');
59	      if (i > 0) kv[p.slice(0, i)] = p.slice(i + 1);
60	    }
61	    if (!name || kv.exit === undefined) return null;
62	    rows.push({
63	      name,
64	      session: kv.session && kv.session !== 'null' ? kv.session : null,
65	      exit: Number(kv.exit),
66	      pid: kv.pid || null,
67	    });
68	  }
69	  return rows;
70	}
71	
72	function parseExpect(spec) {
73	  if (!spec) return null;
74	  const want = {};
75	  for (const part of spec.split(',')) {
76	    const i = part.indexOf('=');
77	    if (i <= 0) return null;
78	    want[part.slice(0, i).trim()] = Number(part.slice(i + 1).trim());
79	  }
80	  return want;
81	}
82	
83	function inspect(root, round, wave, expectSpec) {
84	  const findings = [];
85	  const waveDir = join(resolve(root), '.ufo', 'waves', `round-${round}`, wave);
86	  if (!existsSync(waveDir)) {
87	    return { code: 2, findings: ['WAVE_DIR_ABSENT'], line: `DISPATCH_EVIDENCE: FAIL-CLOSED wave-dir-absent dir=${waveDir}` };
88	  }
89	  const progressPath = join(waveDir, PROGRESS);
90	  if (!existsSync(progressPath)) {
91	    return { code: 2, findings: ['PROGRESS_ABSENT'], line: `DISPATCH_EVIDENCE: FAIL-CLOSED progress-absent path=${progressPath}` };
92	  }
93	  let progressRaw = '';
94	  try { progressRaw = readFileSync(progressPath, 'utf8'); } catch {
95	    return { code: 2, findings: ['PROGRESS_ABSENT'], line: `DISPATCH_EVIDENCE: FAIL-CLOSED progress-unreadable path=${progressPath}` };
96	  }
97	  const rows = parseProgress(progressRaw);
98	  if (!rows || rows.length === 0) {
99	    return { code: 2, findings: ['PROGRESS_ABSENT'], line: `DISPATCH_EVIDENCE: FAIL-CLOSED progress-unparseable path=${progressPath}` };
100	  }
101	  const registryPath = join(waveDir, REGISTRY);
102	  let registry = null;
103	  try {
104	    registry = JSON.parse(readFileSync(registryPath, 'utf8'));
105	  } catch {
106	    return { code: 2, findings: ['REGISTRY_UNREADABLE'], line: `DISPATCH_EVIDENCE: FAIL-CLOSED registry-unreadable path=${registryPath}` };
107	  }
108	
109	  const dead = [];
110	  let sessions = 0;
111	  let exit0 = 0;
112	  let reports = 0;
113	  for (const row of rows) {
114	    const isDead = row.exit !== 0 || !row.session;
115	    if (isDead) dead.push(row.name);
116	    if (row.session) sessions += 1;
117	    if (row.exit === 0) exit0 += 1;
118	    const reportPath = join(waveDir, `${row.name}.md`);
119	    let hasReport = false;
120	    try { hasReport = statSync(reportPath).size > 0; } catch { hasReport = false; }
121	    if (hasReport) reports += 1;
122	    if (row.exit === 0) {
123	      if (!row.session) findings.push(`SESSION_MISMATCH:${row.name}`);
124	      if (!hasReport) findings.push(`REPORT_ABSENT:${row.name}`);
125	    } else if (hasReport) {
126	      findings.push(`DEAD_SEAT_UNCREDITED:${row.name}`);
127	    }
128	  }
129	  const withSession = rows.filter((r) => r.session).length;
130	  if (withSession === 0 && rows.length > 0) findings.push('NOT_A_DISPATCH');
131	
132	  const members = Array.isArray(registry.members) ? registry.members : null;
133	  if (members) {
134	    const noIds = members.every((m) => !m.agentId || m.agentId === 'null');
135	    if (noIds && members.length > 0) findings.push('NOT_A_DISPATCH');
136	    if (Number(registry.planned) !== rows.length) findings.push(`PLAN_MISMATCH:declared=${registry.planned}observed=${rows.length}`);
137	    if (Number(registry.sessionIds) !== sessions) findings.push(`REGISTRY_MISMATCH:sessionIds=${registry.sessionIds}observed=${sessions}`);
138	    if (Number(registry.exit0) !== exit0) findings.push(`REGISTRY_MISMATCH:exit0=${registry.exit0}observed=${exit0}`);
139	    if (Number(registry.reports) !== reports) findings.push(`REGISTRY_MISMATCH:reports=${registry.reports}observed=${reports}`);
140	    const declaredDead = Array.isArray(registry.dead) ? registry.dead.slice().sort() : [];
141	    if (declaredDead.join(',') !== dead.slice().sort().join(',')) {
142	      findings.push(`DEAD_MISMATCH:declared=${declaredDead.join('+') || 'none'}observed=${dead.sort().join('+') || 'none'}`);
143	    }
144	  } else {
145	    findings.push('REGISTRY_UNREADABLE:members-absent');
146	  }
147	
148	  const want = parseExpect(expectSpec);
149	  if (want) {
150	    const observed = { planned: rows.length, sessions, exit0, reports };
151	    for (const [k, v] of Object.entries(want)) {
152	      if (observed[k] !== v) findings.push(`EXPECT_MISMATCH:${k}=${observed[k]} expected=${v}`);
153	    }
154	  }
155	
156	  const unique = [...new Set(findings.map((f) => f.split(':')[0]))];
157	  const line = `DISPATCH_EVIDENCE: ${unique.length ? 'DRIFT' : 'CLEAN'} (seats=${rows.length} sessions=${sessions} exit0=${exit0} reports=${reports} dead=${dead.length})`;
158	  return { code: unique.length ? 1 : 0, findings, unique, line, dead, rows, sessions, exit0, reports };
159	}
