161	function writeFixture(dir, names, opts) {
162	  const waveDir = join(dir, '.ufo', 'waves', 'round-1', 'w1');
163	  mkdirSync(waveDir, { recursive: true });
164	  const lines = [];
165	  for (const n of names) {
166	    const dead = opts.dead && opts.dead.includes(n);
167	    lines.push(`${n}\tpid=1\tsession=${dead ? 'null' : `session_${n}`}\texit=${dead ? -9 : 0}\tstart=1\tend=2\terr=`);
168	    if (!dead || (opts.deadWithReport && opts.deadWithReport.includes(n))) {
169	      writeFileSync(join(waveDir, `${n}.md`), `# ${n}\n\nfixture report\n`);
170	    }
171	  }
172	  writeFileSync(join(waveDir, PROGRESS), `${lines.join('\n')}\n`);
173	  const members = names.map((n) => {
174	    const dead = opts.dead && opts.dead.includes(n);
175	    return { name: n, role: 'executor', kind: 'spawn', agentId: dead ? null : `session_${n}`, exit: dead ? -9 : 0, pid: '1' };
176	  });
177	  const registry = {
178	    schema: 'kumitate-test-dispatch-actual',
179	    wave: 'test',
180	    planned: opts.planned === undefined ? names.length : opts.planned,
181	    progressLines: names.length,
182	    sessionIds: members.filter((m) => m.agentId).length,
183	    exit0: members.filter((m) => m.exit === 0).length,
184	    dead: names.filter((n) => opts.dead && opts.dead.includes(n)),
185	    reports: names.filter((n) => !(opts.dead && opts.dead.includes(n)) || (opts.deadWithReport && opts.deadWithReport.includes(n))).length,
186	    members,
187	  };
188	  writeFileSync(join(waveDir, REGISTRY), `${JSON.stringify(registry, null, 1)}\n`);
189	  return waveDir;
190	}
