192	function selftest() {
193	  const cases = [];
194	  const T = mkdtempSync(join(tmpdir(), 'dispatch-evidence-selftest.'));
195	  const run = (dir, expectSpec) => inspect(dir, 1, 'w1', expectSpec);
196	  try {
197	    {
198	      const d = join(T, 'clean');
199	      writeFixture(d, ['A', 'B', 'C'], {});
200	      const r = run(d);
201	      cases.push(['clean', r.code === 0 && r.line.includes('DISPATCH_EVIDENCE: CLEAN'), r.line]);
202	    }
203	    {
204	      const d = join(T, 'template');
205	      writeFixture(d, ['A', 'B'], {});
206	      const waveDir = join(d, '.ufo', 'waves', 'round-1', 'w1');
207	      const reg = JSON.parse(readFileSync(join(waveDir, REGISTRY), 'utf8'));
208	      for (const m of reg.members) m.agentId = null;
209	      reg.sessionIds = 0;
210	      writeFileSync(join(waveDir, REGISTRY), `${JSON.stringify(reg, null, 1)}\n`);
211	      const r = run(d);
212	      cases.push(['template-registry', r.code === 1 && r.unique.includes('NOT_A_DISPATCH'), r.line]);
213	    }
214	    {
215	      const d = join(T, 'dead');
216	      writeFixture(d, ['A', 'B'], { dead: ['B'], deadWithReport: ['B'] });
217	      const r = run(d);
218	      cases.push(['dead-seat-credited', r.code === 1 && r.unique.includes('DEAD_SEAT_UNCREDITED'), r.line]);
219	    }
220	    {
221	      const d = join(T, 'absent');
222	      writeFixture(d, ['A'], {});
223	      rmSync(join(d, '.ufo', 'waves', 'round-1', 'w1', PROGRESS));
224	      const r = run(d);
225	      cases.push(['progress-absent', r.code === 2 && r.findings.includes('PROGRESS_ABSENT'), r.line]);
226	    }
227	    {
228	      const d = join(T, 'plan');
229	      writeFixture(d, ['A', 'B'], { planned: 9 });
230	      const r = run(d);
231	      cases.push(['plan-mismatch', r.code === 1 && r.unique.includes('PLAN_MISMATCH'), r.line]);
232	    }
233	    {
234	      const d = join(T, 'report');
235	      writeFixture(d, ['A', 'B'], {});
236	      rmSync(join(d, '.ufo', 'waves', 'round-1', 'w1', 'B.md'));
237	      const r = run(d);
238	      cases.push(['report-absent', r.code === 1 && r.unique.includes('REPORT_ABSENT'), r.line]);
239	    }
240	    {
241	      const d = join(T, 'expect');
242	      writeFixture(d, ['A', 'B'], {});
243	      const r = run(d, 'planned=99');
244	      cases.push(['expect-mismatch', r.code === 1 && r.unique.includes('EXPECT_MISMATCH'), r.line]);
245	    }
246	    {
247	      const d = join(T, 'deadset');
248	      writeFixture(d, ['A', 'B'], { dead: ['B'] });
249	      const waveDir = join(d, '.ufo', 'waves', 'round-1', 'w1');
250	      const reg = JSON.parse(readFileSync(join(waveDir, REGISTRY), 'utf8'));
251	      reg.dead = [];
252	      writeFileSync(join(waveDir, REGISTRY), `${JSON.stringify(reg, null, 1)}\n`);
253	      const r = run(d);
254	      cases.push(['dead-mismatch', r.code === 1 && r.unique.includes('DEAD_MISMATCH'), r.line]);
255	    }
256	  } finally {
257	    rmSync(T, { recursive: true, force: true });
258	  }
259	  let passed = 0;
260	  for (const [name, ok, line] of cases) {
261	    process.stdout.write(`${ok ? 'PASS' : 'FAIL'} ${name} — ${line}\n`);
262	    if (ok) passed += 1;
263	  }
264	  const ids = ['NOT_A_DISPATCH', 'DEAD_SEAT_UNCREDITED', 'PROGRESS_ABSENT', 'PLAN_MISMATCH', 'REPORT_ABSENT', 'EXPECT_MISMATCH'];
265	  for (const id of ids) process.stdout.write(`FINDING ${id}\n`);
266	  process.stdout.write(`DISPATCH_EVIDENCE_SELFTEST: ${passed === cases.length ? 'PASS' : 'FAIL'} (${passed}/${cases.length})\n`);
267	  process.stdout.write(`VERDICT: ${passed === cases.length ? 'PASS' : 'FAIL'}\n`);
268	  process.exit(passed === cases.length ? 0 : 1);
269	}
270	
271	const args = parseArgs(process.argv.slice(2));
272	if (args.selftest) selftest();
273	if (!args.round || !args.wave) usage('--root DIR --round N --wave NAME are required (or --selftest)');
274	if (!/^\d+$/.test(String(args.round))) usage('--round must be an integer');
275	if (!/^[A-Za-z0-9._-]+$/.test(String(args.wave))) usage('--wave must be a plain directory name');
276	
277	const result = inspect(args.root, String(args.round), String(args.wave), args.expect);
278	process.stdout.write(`${result.line}\n`);
279	for (const f of result.findings) process.stdout.write(`FINDING ${f}\n`);
280	if (result.code === 2) process.stderr.write(`DISPATCH_EVIDENCE: FAIL-CLOSED contract=${CONTRACT}\n`);
281	process.exit(result.code);

1	#!/usr/bin/env node
2	/**
3	 * dispatch60-probe.mjs — FROZEN counter for kumitate round 60, claim C1 (rule A60).
4	 *
5	 *   node .ufo/waves/round-60/probe/dispatch60-probe.mjs <lane> <rev>
6	 *
7	 * Predicate DISPATCH60_HELD, byte-identical with plan.md §Claims and the report:
8	 * DISPATCH60_HELD — node .ufo/waves/round-60/probe/dispatch60-probe.mjs /home/vgpnk/Projects/shokunin/kumitate-shokunin <rev> prints "DISPATCH60: DISPATCH60_HELD held=10/10 checks=10 rev=<rev> rule=A60" and exits 0.
9	 *
10	 * Ten checks over the committed bytes of <rev> (git archive, never the worktree):
11	 *   A1  scripts/dispatch-evidence.mjs exists at rev and is non-empty.
12	 *   A2  its --selftest exits 0 and prints DISPATCH_EVIDENCE_SELFTEST: PASS (n/n) and VERDICT: PASS.
13	 *   A3  the selftest output names the six finding ids it must be able to produce.
14	 *   A4  SKILL.md carries a gate-registry row for dispatch-evidence naming the entry command.
15	 *   A5  SKILL.md carries a `## Verifiable checklist` task item naming the command.
16	 *   A6  the kumitate-gate-pins-v1 block pins pin.dispatch-evidence with the gate's sha256 at rev.
17	 *   A7  the SCORECARD.md capabilities table carries a dispatch-evidence row.
18	 *   A8  corpus/lessons/round-60.md exists with ## Gate, ## Mistakes and the string dispatch-evidence.
19	 *   A9  the gate registry grew to twenty and SKILL.md's prose integer equals the gate-row count.
20	 *   A10 the gate over this round's committed dispatch record prints DISPATCH_EVIDENCE: CLEAN with seats=32.
21	 *
22	 * Frozen before any data seat scored.
23	 */
24	import { spawnSync } from 'node:child_process';
25	import { createHash } from 'node:crypto';
26	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
27	import { tmpdir } from 'node:os';
28	import { join, resolve } from 'node:path';
29	
30	const RULE = 'A60';
31	const EXPECTED_CHECKS = 10;
32	const GATE = 'scripts/dispatch-evidence.mjs';
33	const EXPECTED_GATES = 20;
34	const FINDINGS = ['NOT_A_DISPATCH', 'DEAD_SEAT_UNCREDITED', 'PROGRESS_ABSENT', 'PLAN_MISMATCH', 'REPORT_ABSENT', 'EXPECT_MISMATCH'];
35	
36	const [laneArg, rev, ...rest] = process.argv.slice(2);
37	if (!laneArg || !rev || rest.length) {
38	  process.stderr.write('DISPATCH60: USAGE node dispatch60-probe.mjs <lane> <rev>\n');
39	  process.exit(64);
40	}
41	const lane = resolve(laneArg);
42	if (!existsSync(join(lane, '.git'))) {
43	  process.stderr.write(`DISPATCH60: USAGE ${JSON.stringify(lane)} is not a git repo\n`);
44	  process.exit(64);
45	}
46	if (!/^[0-9a-f]{7,64}$/.test(rev)) {
47	  process.stderr.write('DISPATCH60: USAGE <rev> must be a lowercase hex object name\n');
48	  process.exit(64);
49	}
50	const sha = (b) => createHash('sha256').update(b).digest('hex');
51	const checks = [];
52	const hold = (id, ok, detail) => checks.push({ id, ok, detail });
53	const T = mkdtempSync(join(tmpdir(), 'a60-probe.'));
54	
55	function finish(code, line) {
56	  rmSync(T, { recursive: true, force: true });
57	  process.stdout.write(line + '\n');
58	  for (const c of checks) process.stdout.write(` | ${c.id} ${c.ok ? 'PASS' : 'MISS'} ${c.detail}`);
59	  if (checks.length) process.stdout.write('\n');
60	  process.exit(code);
61	}
62	
63	try {
64	  const tar = spawnSync('bash', ['-lc',
65	    `git -C ${JSON.stringify(lane)} archive ${JSON.stringify(rev)} | tar -x -C ${JSON.stringify(T)}`],
66	    { encoding: 'utf8', timeout: 180000 });
67	  if (tar.status !== 0) {
68	    process.stderr.write(`DISPATCH60: FAIL-CLOSED rev unreadable (${tar.status})\n`);
69	    rmSync(T, { recursive: true, force: true });
70	    process.exit(2);
71	  }
72	  const readT = (p) => { try { return readFileSync(join(T, p)); } catch { return null; } };
73	  const text = (p) => { const b = readT(p); return b ? b.toString('utf8') : null; };
74	
75	  {
76	    const blob = readT(GATE);
77	    hold('A1', !!blob && blob.length > 0, blob ? `bytes=${blob.length}` : 'gate-absent');
78	  }
79	  let selftestOut = '';
80	  {
81	    const run = spawnSync('node', [join(T, GATE), '--selftest'], { cwd: T, encoding: 'utf8', timeout: 120000 });
82	    selftestOut = `${run.stdout || ''}${run.stderr || ''}`;
83	    const ok = run.status === 0
84	      && /DISPATCH_EVIDENCE_SELFTEST: PASS \(\d+\/\d+\)/.test(selftestOut)
85	      && /VERDICT: PASS/.test(selftestOut);
86	    hold('A2', ok, `exit=${run.status} verdict=${/VERDICT: PASS/.test(selftestOut)}`);
87	  }
88	  {
89	    const missing = FINDINGS.filter((f) => !selftestOut.includes(f));
90	    hold('A3', missing.length === 0, missing.length ? `missing=${missing.join(',')}` : `findings=${FINDINGS.length}`);
91	  }
92	  {
93	    const skill = text('SKILL.md') || '';
94	    const row = skill.split('\n').find((l) => /^\|\s*dispatch-evidence\s*\|\s*gate\s*\|/.test(l));
95	    const ok = !!row && row.includes('scripts/dispatch-evidence.mjs');
96	    hold('A4', ok, row ? 'row-present' : 'row-absent');
97	  }
98	  {
99	    const skill = text('SKILL.md') || '';
100	    const item = skill.split('\n').find((l) => /^\s*- \[ \]/.test(l) && l.includes('scripts/dispatch-evidence.mjs'));
101	    hold('A5', !!item, item ? 'checklist-item' : 'item-absent');
102	  }
103	  {
104	    const score = text('SCORECARD.md') || '';
105	    const block = score.split('<!-- kumitate-gate-pins-v1')[1] || '';
106	    const m = block.match(/pin\.dispatch-evidence=([0-9a-f]{64})/);
107	    const blob = readT(GATE);
108	    const ok = !!m && !!blob && sha(blob) === m[1];
109	    hold('A6', ok, m ? (blob && sha(blob) === m[1] ? 'pin-match' : 'pin-mismatch') : 'pin-absent');
110	  }
111	  {
112	    const score = text('SCORECARD.md') || '';
113	    const row = score.split('\n').find((l) => /^\|\s*`?dispatch-evidence`?\s*\|/.test(l) && l.includes('round 60'));
114	    hold('A7', !!row, row ? 'capability-row' : 'row-absent');
115	  }
116	  {
117	    const lesson = text('corpus/lessons/round-60.md') || '';
118	    const ok = lesson.includes('## Gate') && lesson.includes('## Mistakes') && lesson.includes('dispatch-evidence');
119	    hold('A8', ok, `gate=${lesson.includes('## Gate')} mistakes=${lesson.includes('## Mistakes')} name=${lesson.includes('dispatch-evidence')}`);
120	  }
121	  {
122	    const skill = text('SKILL.md') || '';
123	    const rows = skill.split('\n').filter((l) => /^\|\s*[a-z0-9-]+\s*\|\s*gate\s*\|/.test(l)).length;
124	    const prose = skill.split('\n').find((l) => l.includes('are gates'));
125	    const words = { Twenty: 20, Nineteen: 19, Eighteen: 18, Seventeen: 17 };
126	    let stated = 0;
127	    for (const [w, n] of Object.entries(words)) if (prose && prose.includes(w)) stated = n;
128	    const ok = rows === EXPECTED_GATES && stated === EXPECTED_GATES;
129	    hold('A9', ok, `rows=${rows} prose=${stated}`);
130	  }
131	  {
132	    const run = spawnSync('node', [join(T, GATE), '--root', T, '--round', '60', '--wave', 'w1'],
133	      { cwd: T, encoding: 'utf8', timeout: 120000 });
134	    const out = `${run.stdout || ''}${run.stderr || ''}`;
135	    const ok = run.status === 0 && /DISPATCH_EVIDENCE: CLEAN/.test(out) && /seats=32\b/.test(out);
136	    hold('A10', ok, `exit=${run.status} ${out.split('\n')[0] || 'no-output'}`);
137	  }
138	} catch (err) {
139	  process.stderr.write(`DISPATCH60: FAIL-CLOSED ${err && err.message}\n`);
140	  rmSync(T, { recursive: true, force: true });
141	  process.exit(2);
